(()=>{'use strict';const BASE='https://woongbi-quote-api.woongbts.workers.dev',cache=new Map,pending=new Map,state=new Map;const key=(deviceId,joinType)=>`${deviceId}|${joinType}`;async function request(deviceId,joinType){const k=key(deviceId,joinType);if(cache.has(k))return cache.get(k);if(pending.has(k))return pending.get(k);state.set(k,'loading');const controller=typeof AbortController!=='undefined'?new AbortController():null,timer=controller?setTimeout(()=>controller.abort(),8000):0;const promise=fetch(BASE+'/recommend/plans',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({device_id:deviceId,join_type:joinType}),signal:controller?.signal}).then(async response=>{const data=await response.json().catch(()=>({}));if(!response.ok||data?.ok!==true)throw Error(data?.error||('plan-recommend-'+response.status));const items=Array.isArray(data.items)?data.items:[];cache.set(k,items);state.set(k,'ready');window.dispatchEvent(new CustomEvent('woongbi:plan-recommend-ready',{detail:{device_id:deviceId,join_type:joinType,items}}));return items}).catch(error=>{state.set(k,'unavailable');window.dispatchEvent(new CustomEvent('woongbi:plan-recommend-unavailable',{detail:{device_id:deviceId,join_type:joinType}}));throw error}).finally(()=>{if(timer)clearTimeout(timer);pending.delete(k)});pending.set(k,promise);return promise}window.WoongbiPlanRecommendApi={load:(deviceId,joinType)=>deviceId&&joinType?request(deviceId,joinType):Promise.resolve([]),getCached:(deviceId,joinType)=>cache.get(key(deviceId,joinType))||[],status:(deviceId,joinType)=>state.get(key(deviceId,joinType))||'idle',clear:()=>{cache.clear();pending.clear();state.clear()}}})();
